content:
:root {
  --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;

  /* カラーパレット */
  --bg-primary: #f8fafc;
  --bg-secondary: #f1f5f9;
  --bg-card: #ffffff;
  --bg-card-hover: #fafafa;
  --bg-modal: #ffffff;
  --bg-backdrop: rgba(15, 23, 42, 0.55);

  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-subtle: #94a3b8;
  --text-inverse: #ffffff;

  --border-light: #e2e8f0;
  --border-focus: #3b82f6;

  /* アクションカラー */
  --primary: #3b82f6;
  --primary-hover: #2563eb;
  --primary-light: #eff6ff;

  --secondary: #64748b;
  --secondary-hover: #475569;
  --secondary-light: #f1f5f9;

  --danger: #ef4444;
  --danger-hover: #dc2626;
  --danger-light: #fef2f2;

  /* 優先度カラー */
  --priority-high-bg: #fef2f2;
  --priority-high-text: #b91c1c;
  --priority-high-border: #fca5a5;

  --priority-med-bg: #fffbeb;
  --priority-med-text: #b45309;
  --priority-med-border: #fcd34d;

  --priority-low-bg: #f0fdf4;
  --priority-low-text: #15803d;
  --priority-low-border: #86efac;

  /* 影と角丸 */
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.08);
  --shadow-card: 0 1px 3px rgba(0, 0, 0, 0.06), 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow-card-drag: 0 16px 32px rgba(15, 23, 42, 0.18), 0 6px 12px rgba(15, 23, 42, 0.1);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --radius-full: 9999px;

  --transition-fast: 0.15s ease;
  --transition-normal: 0.25s ease;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

/* アプリケーション全体レイアウト */
.app-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  max-width: 1440px;
  margin: 0 auto;
  padding: 24px 20px 40px;
}

/* ヘッダー */
.header {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 24px;
}

@media (min-width: 768px) {
  .header {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.header-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 8px;
}

.header-subtitle {
  font-size: 0.925rem;
  color: var(--text-muted);
  margin-top: 4px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* ツールバー (検索・フィルタリング) */
.toolbar {
  display: flex;
  flex-direction: column;
  gap: 12px;
  background-color: var(--bg-card);
  padding: 14px 18px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-sm);
  margin-bottom: 24px;
}

@media (min-width: 640px) {
  .toolbar {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.search-input {
  flex: 1;
  width: 100%;
  padding: 10px 14px;
  font-size: 0.95rem;
  color: var(--text-main);
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast), background-color var(--transition-fast);
}

.search-input:focus {
  background-color: var(--bg-card);
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.filter-select {
  padding: 10px 14px;
  font-size: 0.9rem;
  color: var(--text-main);
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  outline: none;
  cursor: pointer;
  min-width: 150px;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.filter-select:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

/* ボタンスタイル */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 0.9rem;
  font-weight: 600;
  padding: 10px 18px;
  border-radius: var(--radius-sm);
  border: none;
  cursor: pointer;
  transition: background-color var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
  white-space: nowrap;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background-color: var(--primary);
  color: var(--text-inverse);
  box-shadow: 0 2px 4px rgba(59, 130, 246, 0.3);
}

.btn-primary:hover {
  background-color: var(--primary-hover);
  box-shadow: 0 4px 8px rgba(59, 130, 246, 0.4);
}

.btn-secondary {
  background-color: var(--secondary-light);
  color: var(--secondary);
  border: 1px solid var(--border-light);
}

.btn-secondary:hover {
  background-color: var(--border-light);
  color: var(--secondary-hover);
}

.btn-danger {
  background-color: var(--danger-light);
  color: var(--danger);
  border: 1px solid #fecaca;
}

.btn-danger:hover {
  background-color: var(--danger);
  color: var(--text-inverse);
}

.btn-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  padding: 6px;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  cursor: pointer;
  transition: color var(--transition-fast), background-color var(--transition-fast);
}

.btn-icon:hover {
  color: var(--text-main);
  background-color: var(--bg-secondary);
}

.btn-icon.delete-btn:hover {
  color: var(--danger);
  background-color: var(--danger-light);
}

/* カンバンボードコンテナ */
.board-container {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
  align-items: start;
  flex: 1;
}

@media (min-width: 768px) {
  .board-container {
    grid-template-columns: repeat(3, minmax(280px, 1fr));
    gap: 24px;
    overflow-x: auto;
    padding-bottom: 12px;
  }
}

/* カンバン列 */
.kanban-column {
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  min-height: 480px;
  max-height: calc(100vh - 220px);
  padding: 16px;
  box-shadow: var(--shadow-sm);
  transition: background-color var(--transition-fast), border-color var(--transition-fast);
}

.kanban-column.drag-over {
  background-color: #f0f7ff;
  border-color: var(--primary);
}

/* カンバン列ヘッダー */
.column-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--border-light);
}

.column-title-badge {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 1rem;
  color: var(--text-main);
}

.column-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
  background-color: var(--bg-card);
  border: 1px solid var(--border-light);
  padding: 2px 10px;
  border-radius: var(--radius-full);
}

/* タスク追加ボタン (列下部) */
.column-add-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px;
  margin-top: 12px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  background-color: transparent;
  border: 2px dashed var(--border-light);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.column-add-btn:hover {
  color: var(--primary);
  border-color: var(--primary);
  background-color: rgba(59, 130, 246, 0.05);
}

/* タスク一覧 */
.task-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
  overflow-y: auto;
  padding-right: 4px;
}

.task-list::-webkit-scrollbar {
  width: 6px;
}

.task-list::-webkit-scrollbar-track {
  background: transparent;
}

.task-list::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: var(--radius-full);
}

.task-list::-webkit-scrollbar-thumb:hover {
  background: #94a3b8;
}

/* 空プレースホルダー */
.empty-column-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 32px 16px;
  text-align: center;
  color: var(--text-subtle);
  border: 2px dashed #cbd5e1;
  border-radius: var(--radius-md);
  background-color: rgba(255, 255, 255, 0.4);
  font-size: 0.875rem;
  gap: 6px;
}

/* タスクカード */
.task-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 16px;
  box-shadow: var(--shadow-card);
  cursor: grab;
  user-select: none;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast), border-color var(--transition-fast);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.task-card:hover {
  box-shadow: var(--shadow-md);
  border-color: #cbd5e1;
  transform: translateY(-2px);
}

.task-card:active {
  cursor: grabbing;
}

.task-card-dragging {
  opacity: 0.45;
  transform: rotate(2deg) scale(0.98);
  box-shadow: var(--shadow-card-drag);
  border-color: var(--primary);
}

/* カードヘッダー */
.task-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.task-priority-badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  line-height: 1;
  border: 1px solid transparent;
}

.priority-high {
  background-color: var(--priority-high-bg);
  color: var(--priority-high-text);
  border-color: var(--priority-high-border);
}

.priority-medium {
  background-color: var(--priority-med-bg);
  color: var(--priority-med-text);
  border-color: var(--priority-med-border);
}

.priority-low {
  background-color: var(--priority-low-bg);
  color: var(--priority-low-text);
  border-color: var(--priority-low-border);
}

.task-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* カードコンテンツ */
.task-title {
  font-size: 0.975rem;
  font-weight: 600;
  color: var(--text-main);
  line-height: 1.4;
  word-break: break-word;
}

.task-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.45;
  white-space: pre-line;
  word-break: break-word;
  max-height: 4.35em;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
}

/* カードメタ情報 */
.task-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 10px;
  border-top: 1px solid var(--border-light);
  font-size: 0.8rem;
  color: var(--text-muted);
}

.task-assignee {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-weight: 500;
}

.task-date {
  color: var(--text-subtle);
  font-size: 0.775rem;
}

/* クイック移動セレクター (スマホ・アクセシビリティ用) */
.quick-move-select {
  width: 100%;
  margin-top: 4px;
  padding: 6px 10px;
  font-size: 0.8rem;
  color: var(--text-muted);
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  outline: none;
  cursor: pointer;
  transition: border-color var(--transition-fast);
}

.quick-move-select:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}

/* モーダルダイアログ */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background-color: var(--bg-backdrop);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 1000;
  animation: fadeIn 0.15s ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.modal-content {
  background-color: var(--bg-modal);
  border-radius: var(--radius-lg);
  width: 100%;
  max-width: 520px;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: slideUp 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  border-bottom: 1px solid var(--border-light);
}

.modal-header h2 {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-main);
}

.modal-body {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 18px;
  max-height: 75vh;
  overflow-y: auto;
}

.modal-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  padding: 16px 24px;
  background-color: var(--bg-secondary);
  border-top: 1px solid var(--border-light);
}

/* フォーム要素 */
.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-main);
}

.form-input,
.form-select,
.form-textarea {
  width: 100%;
  padding: 10px 14px;
  font-size: 0.95rem;
  font-family: inherit;
  color: var(--text-main);
  background-color: #ffffff;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-textarea {
  resize: vertical;
  min-height: 96px;
  line-height: 1.5;
}

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.form-input::placeholder,
.form-textarea::placeholder {
  color: var(--text-subtle);
}

import type { DragEvent } from 'react';

export type ColumnId = 'todo' | 'in_progress' | 'done';

export type Priority = 'high' | 'medium' | 'low';

export interface TaskItem {
  id: string;
  title: string;
  description: string;
  status: ColumnId;
  priority: Priority;
  assignee: string;
  createdAt: string;
}

export interface ColumnData {
  id: ColumnId;
  title: string;
  color: string;
}

export interface TaskCardProps {
  task: TaskItem;
  onDragStart: (e: DragEvent, id: string) => void;
  onEdit: (task: TaskItem) => void;
  onDelete: (id: string) => void;
  onMoveColumn: (id: string, nextStatus: ColumnId) => void;
}

export interface KanbanColumnProps {
  column: ColumnData;
  tasks: TaskItem[];
  onDragOver: (e: DragEvent) => void;
  onDrop: (e: DragEvent, status: ColumnId) => void;
  onDragStart: (e: DragEvent, id: string) => void;
  onEditTask: (task: TaskItem) => void;
  onDeleteTask: (id: string) => void;
  onMoveTask: (id: string, nextStatus: ColumnId) => void;
  onAddTaskClick: (status: ColumnId) => void;
}

export interface TaskModalProps {
  isOpen: boolean;
  initialTask: TaskItem | null;
  defaultStatus: ColumnId;
  onClose: () => void;
  onSave: (taskData: Omit<TaskItem, 'id' | 'createdAt'> & { id?: string }) => void;
}

import { useState } from 'react';
import type { DragEvent, ChangeEvent } from 'react';
import { Pencil, Trash2, User, Calendar } from 'lucide-react';
import type { TaskCardProps, ColumnId, Priority } from '../types';

const PRIORITY_LABELS: Record<Priority, string> = {
  high: '高',
  medium: '中',
  low: '低',
};

const PRIORITY_CLASSES: Record<Priority, string> = {
  high: 'priority-high',
  medium: 'priority-medium',
  low: 'priority-low',
};

const STATUS_LABELS: Record<ColumnId, string> = {
  todo: '未着手',
  in_progress: '作業中',
  done: '完了',
};

const TaskCard = ({
  task,
  onDragStart,
  onEdit,
  onDelete,
  onMoveColumn,
}: TaskCardProps) => {
  const [isDragging, setIsDragging] = useState<boolean>(false);

  const handleDragStart = (e: DragEvent) => {
    setIsDragging(true);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', task.id);
    onDragStart?.(e, task.id);
  };

  const handleDragEnd = () => {
    setIsDragging(false);
  };

  const handleSelectChange = (e: ChangeEvent<HTMLSelectElement>) => {
    const nextStatus = e.target.value as ColumnId;
    if (nextStatus !== task.status) {
      onMoveColumn?.(task.id, nextStatus);
    }
  };

  const cardClassName = isDragging ? 'task-card task-card-dragging' : 'task-card';
  const priorityClassName = `task-priority-badge ${PRIORITY_CLASSES[task.priority]}`;

  return (
    <div
      className={cardClassName}
      draggable
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
    >
      <div className="task-card-header">
        <span className={priorityClassName}>
          {PRIORITY_LABELS[task.priority]}
        </span>
        <div className="task-actions">
          <button
            type="button"
            className="btn-icon"
            onClick={() => onEdit?.(task)}
            title="タスクを編集"
            aria-label="タスクを編集"
          >
            <Pencil size={15} />
          </button>
          <button
            type="button"
            className="btn-icon delete-btn"
            onClick={() => onDelete?.(task.id)}
            title="タスクを削除"
            aria-label="タスクを削除"
          >
            <Trash2 size={15} />
          </button>
        </div>
      </div>

      <h3 className="task-title">{task.title}</h3>

      {task.description && (
        <p className="task-desc">{task.description}</p>
      )}

      <div className="task-meta">
        <span className="task-assignee">
          <User size={13} />
          {task.assignee || '未設定'}
        </span>
        <span className="task-date">
          <Calendar size={13} style={{ marginRight: '3px', verticalAlign: 'text-bottom' }} />
          {task.createdAt}
        </span>
      </div>

      <select
        className="quick-move-select"
        value={task.status}
        onChange={handleSelectChange}
        aria-label="ステータスを変更"
      >
        <option value="todo">{STATUS_LABELS.todo}へ移動</option>
        <option value="in_progress">{STATUS_LABELS.in_progress}へ移動</option>
        <option value="done">{STATUS_LABELS.done}へ移動</option>
      </select>
    </div>
  );
};

export default TaskCard;

import { useState } from 'react';
import type { DragEvent } from 'react';
import { Plus, Inbox } from 'lucide-react';
import type { KanbanColumnProps } from '../types';
import TaskCard from './TaskCard';

const KanbanColumn = ({
  column,
  tasks = [],
  onDragOver,
  onDrop,
  onDragStart,
  onEditTask,
  onDeleteTask,
  onMoveTask,
  onAddTaskClick,
}: KanbanColumnProps) => {
  const [isDragOver, setIsDragOver] = useState<boolean>(false);

  const handleDragOver = (e: DragEvent) => {
    e.preventDefault();
    setIsDragOver(true);
    onDragOver?.(e);
  };

  const handleDragLeave = () => {
    setIsDragOver(false);
  };

  const handleDrop = (e: DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
    onDrop?.(e, column.id);
  };

  const columnClassName = isDragOver ? 'kanban-column drag-over' : 'kanban-column';

  return (
    <section
      className={columnClassName}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      aria-label={`${column.title} 列`}
    >
      <div className="column-header">
        <div className="column-title-badge">
          <span
            style={{
              width: '10px',
              height: '10px',
              borderRadius: '50%',
              backgroundColor: column.color,
              display: 'inline-block',
            }}
          />
          <span>{column.title}</span>
        </div>
        <span className="column-count">{tasks.length}</span>
      </div>

      <div className="task-list">
        {tasks.length === 0 ? (
          <div className="empty-column-placeholder">
            <Inbox size={28} />
            <span>タスクがありません</span>
          </div>
        ) : (
          tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onDragStart={onDragStart}
              onEdit={onEditTask}
              onDelete={onDeleteTask}
              onMoveColumn={onMoveTask}
            />
          ))
        )}
      </div>

      <button
        type="button"
        className="column-add-btn"
        onClick={() => onAddTaskClick?.(column.id)}
      >
        <Plus size={16} />
        <span>タスクを追加</span>
      </button>
    </section>
  );
};

export default KanbanColumn;

import { useState, useEffect } from 'react';
import type { FormEvent, MouseEvent } from 'react';
import { X } from 'lucide-react';
import type { TaskModalProps, ColumnId, Priority } from '../types';

const TaskModal = ({
  isOpen,
  initialTask,
  defaultStatus,
  onClose,
  onSave,
}: TaskModalProps) => {
  const [title, setTitle] = useState<string>('');
  const [description, setDescription] = useState<string>('');
  const [status, setStatus] = useState<ColumnId>('todo');
  const [priority, setPriority] = useState<Priority>('medium');
  const [assignee, setAssignee] = useState<string>('');
  const [errorMessage, setErrorMessage] = useState<string>('');

  useEffect(() => {
    if (initialTask) {
      setTitle(initialTask.title);
      setDescription(initialTask.description);
      setStatus(initialTask.status);
      setPriority(initialTask.priority);
      setAssignee(initialTask.assignee);
    } else {
      setTitle('');
      setDescription('');
      setStatus(defaultStatus || 'todo');
      setPriority('medium');
      setAssignee('');
    }
    setErrorMessage('');
  }, [initialTask, defaultStatus, isOpen]);

  if (!isOpen) {
    return null;
  }

  const handleBackdropClick = (e: MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) {
      onClose?.();
    }
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const trimmedTitle = title.trim();

    if (!trimmedTitle) {
      setErrorMessage('タイトルを入力してください。');
      return;
    }

    onSave?.({
      ...(initialTask ? { id: initialTask.id } : {}),
      title: trimmedTitle,
      description: description.trim(),
      status,
      priority,
      assignee: assignee.trim(),
    });

    onClose?.();
  };

  return (
    <div className="modal-backdrop" onClick={handleBackdropClick} role="presentation">
      <div className="modal-content" role="dialog" aria-modal="true" aria-labelledby="modal-title">
        <div className="modal-header">
          <h2 id="modal-title">
            {initialTask ? 'タスクを編集' : '新しいタスクを作成'}
          </h2>
          <button
            type="button"
            className="btn-icon"
            onClick={onClose}
            aria-label="閉じる"
          >
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="modal-body">
            <div className="form-group">
              <label className="form-label" htmlFor="task-title-input">
                タイトル <span style={{ color: 'var(--danger)' }}>*</span>
              </label>
              <input
                id="task-title-input"
                type="text"
                className="form-input"
                placeholder="例: ログイン機能の画面設計"
                value={title}
                onChange={(e) => {
                  setTitle(e.target.value);
                  if (errorMessage) setErrorMessage('');
                }}
                autoFocus
              />
              {errorMessage && (
                <span style={{ fontSize: '0.8rem', color: 'var(--danger)', marginTop: '2px' }}>
                  {errorMessage}
                </span>
              )}
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="task-desc-input">
                詳細説明
              </label>
              <textarea
                id="task-desc-input"
                className="form-textarea"
                placeholder="タスクの要件や注意事項を入力してください..."
                value={description}
                onChange={(e) => setDescription(e.target.value)}
              />
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="task-status-input">
                ステータス
              </label>
              <select
                id="task-status-input"
                className="form-select"
                value={status}
                onChange={(e) => setStatus(e.target.value as ColumnId)}
              >
                <option value="todo">未着手</option>
                <option value="in_progress">作業中</option>
                <option value="done">完了</option>
              </select>
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="task-priority-input">
                優先度
              </label>
              <select
                id="task-priority-input"
                className="form-select"
                value={priority}
                onChange={(e) => setPriority(e.target.value as Priority)}
              >
                <option value="high">高</option>
                <option value="medium">中</option>
                <option value="low">低</option>
              </select>
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="task-assignee-input">
                担当者
              </label>
              <input
                id="task-assignee-input"
                type="text"
                className="form-input"
                placeholder="例: 山田 太郎"
                value={assignee}
                onChange={(e) => setAssignee(e.target.value)}
              />
            </div>
          </div>

          <div className="modal-footer">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={onClose}
            >
              キャンセル
            </button>
            <button type="submit" className="btn btn-primary">
              {initialTask ? '更新する' : '追加する'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TaskModal;

