const App = () => {
  const [tasks, setTasks] = useState<TaskItem[]>(INITIAL_TASKS);
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [priorityFilter, setPriorityFilter] = useState<string>('all');
  const [draggedTaskId, setDraggedTaskId] = useState<string | null>(null);

  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [editingTask, setEditingTask] = useState<TaskItem | null>(null);
  const [modalDefaultStatus, setModalDefaultStatus] = useState<ColumnId>('todo');

  const handleDragStart = (_e: DragEvent, id: string) => {
    setDraggedTaskId(id);
  };

  const handleDragOver = (e: DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: DragEvent, targetStatus: ColumnId) => {
    e.preventDefault();
    const taskId = draggedTaskId || e.dataTransfer.getData('text/plain');

    if (!taskId) return;

    setTasks((prevTasks) =>
      prevTasks.map((t) => (t.id === taskId ? { ...t, status: targetStatus } : t))
    );
    setDraggedTaskId(null);
  };

  const handleMoveTask = (id: string, nextStatus: ColumnId) => {
    setTasks((prevTasks) =>
      prevTasks.map((t) => (t.id === id ? { ...t, status: nextStatus } : t))
    );
  };

  const handleDeleteTask = (id: string) => {
    setTasks((prevTasks) => prevTasks.filter((t) => t.id !== id));
  };

  const handleOpenCreateModal = (status: ColumnId = 'todo') => {
    setEditingTask(null);
    setModalDefaultStatus(status);
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (task: TaskItem) => {
    setEditingTask(task);
    setModalDefaultStatus(task.status);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingTask(null);
  };

  const handleSaveTask = (
    taskData: Omit<TaskItem, 'id' | 'createdAt'> & { id?: string }
  ) => {
    if (taskData.id) {
      setTasks((prevTasks) =>
        prevTasks.map((t) =>
          t.id === taskData.id
            ? {
                ...t,
                title: taskData.title,
                description: taskData.description,
                status: taskData.status,
                priority: taskData.priority,
                assignee: taskData.assignee,
              }
            : t
        )
      );
    } else {
      const now = new Date();
      const year = now.getFullYear();
      const month = String(now.getMonth() + 1).padStart(2, '0');
      const day = String(now.getDate()).padStart(2, '0');

      const newTask: TaskItem = {
        id: `task-${Date.now()}`,
        title: taskData.title,
        description: taskData.description,
        status: taskData.status,
        priority: taskData.priority,
        assignee: taskData.assignee,
        createdAt: `${year}/${month}/${day}`,
      };

      setTasks((prevTasks) => [...prevTasks, newTask]);
    }
  };

  const filteredTasks = tasks.filter((task) => {
    const matchesSearch =
      task.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      task.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      task.assignee.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesPriority =
      priorityFilter === 'all' || task.priority === priorityFilter;

    return matchesSearch && matchesPriority;
  });

  return (
    <div className="app-container">
      <header className="header">
        <div>
          <h1 className="header-title">
            <Kanban size={30} style={{ color: 'var(--primary)' }} />
            カンバンボード
          </h1>
          <p className="header-subtitle">
            カードをドラッグ＆ドロップして進捗ステータスをスムーズに管理できます
          </p>
        </div>

        <div className="header-actions">
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => handleOpenCreateModal('todo')}
          >
            <Plus size={18} />
            新規タスク作成
          </button>
        </div>
      </header>

      <section className="toolbar">
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flex: 1 }}>
          <Search size={18} style={{ color: 'var(--text-muted)' }} />
          <input
            type="text"
            className="search-input"
            placeholder="タイトル・詳細・担当者名で検索..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <Filter size={18} style={{ color: 'var(--text-muted)' }} />
          <select
            className="filter-select"
            value={priorityFilter}
            onChange={(e) => setPriorityFilter(e.target.value)}
            aria-label="優先度で絞り込み"
          >
            <option value="all">すべての優先度</option>
            <option value="high">優先度: 高</option>
            <option value="medium">優先度: 中</option>
            <option value="low">優先度: 低</option>
          </select>
        </div>
      </section>

      <main className="board-container">
        {COLUMNS.map((col) => {
          const colTasks = filteredTasks.filter((t) => t.status === col.id);
          return (
            <KanbanColumn
              key={col.id}
              column={col}
              tasks={colTasks}
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onDragStart={handleDragStart}
              onEditTask={handleOpenEditModal}
              onDeleteTask={handleDeleteTask}
              onMoveTask={handleMoveTask}
              onAddTaskClick={handleOpenCreateModal}
            />
          );
        })}
      </main>

      <TaskModal
        isOpen={isModalOpen}
        initialTask={editingTask}
        defaultStatus={modalDefaultStatus}
        onClose={handleCloseModal}
        onSave={handleSaveTask}
      />
    </div>
  );
};

